import Database from "better-sqlite3";
import path from "path";

const DB_PATH = path.resolve(process.cwd(), "notes.db");

let _db: Database.Database | null = null;

export function getDb(): Database.Database {
  if (!_db) {
    _db = new Database(DB_PATH);
    _db.pragma("journal_mode = WAL");
    _db.exec(`
      CREATE TABLE IF NOT EXISTS notes (
        id        INTEGER PRIMARY KEY AUTOINCREMENT,
        title     TEXT    NOT NULL,
        content   TEXT    NOT NULL,
        created_at DATETIME DEFAULT (datetime('now'))
      )
    `);
  }
  return _db;
}

export function insertNote(title: string, content: string): number {
  const db = getDb();
  const stmt = db.prepare(
    "INSERT INTO notes (title, content) VALUES (?, ?)"
  );
  const info = stmt.run(title, content);
  return info.lastInsertRowid as number;
}

import { createAPIFileRoute } from "@tanstack/start/api";
import { streamText, tool } from "ai";
import { openai } from "@ai-sdk/openai";
import { z } from "zod";
import { insertNote } from "~/lib/db";

export const APIRoute = createAPIFileRoute("/api/chat")({
  POST: async ({ request }) => {
    const { messages } = await request.json();

    const result = streamText({
      model: openai("gpt-4o-mini"),
      system:
        "You are a helpful assistant. When the user asks you to create or save a note, " +
        "use the createNote tool. Always confirm after notes are saved.",
      messages,
      tools: {
        createNote: tool({
          description:
            "Creates and saves a note to the database. Requires user approval before executing.",
          parameters: z.object({
            title: z.string().describe("The title of the note"),
            content: z.string().describe("The body content of the note"),
          }),
          // No execute function → tool becomes "human-in-the-loop" and streams
          // a tool-call part that the client must resolve via addToolResult.
        }),
      },
      maxSteps: 5,
      onStepFinish({ toolCalls, toolResults }) {
        // When the client sends back tool results that were approved,
        // execute the database write here on the server.
        for (const result of toolResults ?? []) {
          if (result.toolName === "createNote") {
            const r = result.result as { approved?: boolean };
            if (r?.approved) {
              const args = toolCalls?.find(
                (tc) => tc.toolCallId === result.toolCallId
              )?.args as { title: string; content: string } | undefined;

              if (args) {
                try {
                  const id = insertNote(args.title, args.content);
                  // Patch result in-place so the LLM sees the noteId
                  (result.result as Record<string, unknown>).noteId = id;
                } catch (err) {
                  console.error("DB insert error:", err);
                  (result.result as Record<string, unknown>).error = String(err);
                }
              }
            }
          }
        }
      },
    });

    return result.toDataStreamResponse();
  },
});

