  }

  return requestHandler(startRequestResolver)
}

async function handleRedirectResponse(
  response: HandlerCallbackResult,
  request: Request,
  getRouter: () => Promise<AnyRouter>,
): Promise<SsrResponse> {
  const ssrResponse = normalizeSsrResponse(response)
