import { createAPIFileRoute } from "@tanstack/start/api";
import { streamText, tool } from "ai";
import { openai } from "@ai-sdk/openai";
import { z } from "zod";
import { insertNote } from "~/lib/db";

export const APIRoute = createAPIFileRoute("/api/chat")({
  POST: async ({ request }) => {
    const { messages } = await request.json();

    const result = streamText({
      model: openai("gpt-4o-mini"),
      system:
        "You are a helpful assistant. When the user asks you to create or save a note, " +
        "use the createNote tool. Always confirm after notes are saved.",
      messages,
      tools: {
        createNote: tool({
          description:
            "Creates and saves a note to the database. Requires user approval before executing.",
          parameters: z.object({
            title: z.string().describe("The title of the note"),
            content: z.string().describe("The body content of the note"),
          }),
          // No `execute` function → becomes a human-in-the-loop tool call.
          // The client must call addToolResult({ toolCallId, result }) to proceed.
        }),
      },
      maxSteps: 5,
    });

    return result.toDataStreamResponse();
  },
});

import { createAPIFileRoute } from "@tanstack/start/api";
import { streamText, tool } from "ai";
import { openai } from "@ai-sdk/openai";
import { z } from "zod";
import { insertNote } from "~/lib/db";

export const APIRoute = createAPIFileRoute("/api/chat")({
  POST: async ({ request }) => {
    const { messages } = (await request.json()) as {
      messages: Array<{
        role: string;
        content:
          | string
          | Array<{
              type: string;
              toolCallId?: string;
              toolName?: string;
              result?: unknown;
              args?: Record<string, unknown>;
            }>;
      }>;
    };

    // Process any pending approved tool results before streaming.
    // When the client calls addToolResult({ result: { approved: true } }),
    // useChat re-submits all messages including the tool result.
    // We detect those here and write to the DB.
    for (const message of messages) {
      if (message.role === "tool" && Array.isArray(message.content)) {
        for (const part of message.content) {
          if (
            part.type === "tool-result" &&
            part.toolName === "createNote"
          ) {
            const toolResult = part.result as {
              approved?: boolean;
              noteId?: number;
              _written?: boolean;
            };

            // Only write once (guard with _written flag)
            if (toolResult?.approved === true && !toolResult._written) {
              // Find the corresponding tool call to get the args
              const toolCallId = part.toolCallId;
              outer: for (const msg of messages) {
                if (msg.role === "assistant" && Array.isArray(msg.content)) {
                  for (const p of msg.content) {
                    if (
                      p.type === "tool-call" &&
                      p.toolCallId === toolCallId &&
                      p.toolName === "createNote"
                    ) {
                      try {
                        const args = p.args as {
                          title: string;
                          content: string;
                        };
                        const noteId = insertNote(args.title, args.content);
                        // Patch the result so LLM sees the noteId
                        toolResult.noteId = noteId;
                        toolResult._written = true;
                      } catch (err) {
                        console.error("Failed to insert note:", err);
                      }
                      break outer;
                    }
                  }
                }
              }
            }
          }
        }
      }
