import { createAPIFileRoute } from "@tanstack/start/api";
import { streamText, tool } from "ai";
import { openai } from "@ai-sdk/openai";
import { z } from "zod";
import { insertNote } from "~/lib/db";

// Shape of the raw message body sent by useChat
type RawMessage = {
  role: string;
  content:
    | string
    | Array<{
        type: string;
        toolCallId?: string;
        toolName?: string;
        result?: unknown;
        args?: unknown;
      }>;
  toolInvocations?: Array<{
    state: string;
    toolCallId: string;
    toolName: string;
    args: unknown;
    result?: unknown;
  }>;
};

export const APIRoute = createAPIFileRoute("/api/chat")({
  POST: async ({ request }) => {
    const body = (await request.json()) as { messages: RawMessage[] };
    const rawMessages = body.messages;

    // ─── DB write on approval ─────────────────────────────────────────────
    // useChat sends back messages where an assistant message includes a
    // toolInvocation with state "result" and result.approved = true.
    // We write to the DB here, before forwarding to the LLM.
    for (const message of rawMessages) {
      if (message.role === "assistant" && Array.isArray(message.toolInvocations)) {
        for (const inv of message.toolInvocations) {
          if (
            inv.toolName === "createNote" &&
            inv.state === "result"
          ) {
            const result = inv.result as {
              approved?: boolean;
              noteId?: number;
              _written?: boolean;
            };
            if (result?.approved === true && !result._written) {
              try {
                const args = inv.args as { title: string; content: string };
                const noteId = insertNote(args.title, args.content);
                result.noteId = noteId;
                result._written = true;
              } catch (err) {
                console.error("Failed to insert note:", err);
              }
            }
          }
        }
      }
    }

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const result = streamText({
      model: openai("gpt-4o-mini"),
      system:
        "You are a helpful assistant. When the user asks you to create or save a note, " +
        "use the createNote tool. Always confirm to the user after notes are saved, " +
        "mentioning the note ID if available.",
      messages: rawMessages as Parameters<typeof streamText>[0]["messages"],
      tools: {
        createNote: tool({
          description:
            "Creates and saves a note to the database. " +
            "Requires explicit user approval before executing. " +
            "Do not re-invoke after approval.",
          parameters: z.object({
            title: z.string().describe("The title of the note"),
            content: z.string().describe("The body content of the note"),
          }),
          // No execute → human-in-the-loop: the stream pauses, returning
          // a tool-call part. The client resolves it via addToolResult().
        }),
      },
      maxSteps: 5,
    });

    return result.toDataStreamResponse();
  },
});

